"""Compile reviewed DS423+ and own 5U support for SQL22; catalogs16-21 remain frozen."""
from __future__ import annotations
import argparse
import importlib.util
import json
import os
from pathlib import Path
import sys
import tempfile
ROOT = Path(__file__).absolute().parents[1]
_spec = importlib.util.spec_from_file_location('hardware_catalog_helpers22', ROOT/'tools/build_hardware_catalog21.py')
g = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(g)
c = g.c
SOURCE='development/hardware/catalog-diskstation-v1.json'
FACTS='development/hardware/synology-ds423plus.facts.json'
LOCK='development/hardware/catalog-schema22.lock.json'
BASE='development/server/database/021-synology-hardware.sql'
SERVER='development/server/src/RackClick.Server/DiskStationHardwareProfiles.Generated.cs'
FRONTEND='development/frontend/src/hardware-diskstation.generated.json'
SQL='development/server/database/022-diskstation-hardware.sql'
MANIFEST='development/hardware/catalog-diskstation.manifest.json'
TARGETS='development/server/src/RackClick.Server/DiskStationHardware.Generated.targets'
STATE='curated_development_not_a_release'
EXPECTED_SOURCE=json.loads('{"catalogKey":"rackclick-diskstation-01","definitions":[{"color":"#28292a","dimensionsMm":{"depth":223,"height":166,"width":199},"groups":[{"count":2,"face":"rear","key":"rear-lan","name":"LAN","powerRole":"unspecified","prefix":"LAN ","type":"rj45"}],"identity":{"family":"DiskStation","manufacturer":"Synology","model":"DS423+","sku":"DS423+"},"key":"synology-ds423plus","kind":"desktop","passthrough":null,"provenance":{"assets":[],"kind":"manufacturer-specification","source":"https://global.download.synology.com/download/Document/Hardware/HIG/DiskStation/23-year/DS423%2B/enu/DS423p_HIG_enu.pdf"},"rackUnits":0,"revision":"synology-ds423plus-20261030-v1","slots":[]},{"color":"#46505c","dimensionsMm":{"depth":300,"height":222,"width":482.6},"groups":[],"identity":{"family":null,"manufacturer":null,"model":null,"sku":null},"key":"shelf-5u","kind":"shelf","passthrough":null,"provenance":{"assets":[],"kind":"own-synthetic","source":"development/hardware/synology-ds423plus.facts.json#ownSyntheticSupport"},"rackUnits":5,"revision":"mount-support-20261030-v1","slots":[{"dimensionsMm":{"depth":300,"height":190,"width":440},"key":"main"}]}],"formatVersion":1}')
EXPECTED_FACTS=json.loads('{"datasheet":{"pdfSha256":"236e3424594a688c21eeb63d24a455e1621d65eb741168221ee9055cbb4e4cec","revision":"DS423plus-2023-ENU-REV000","url":"https://global.download.synology.com/download/Document/Hardware/DataSheet/DiskStation/23-year/DS423%2B/enu/Synology_DS423%2B_Data_Sheet_enu.pdf"},"facts":{"depthMm":223,"ethernetMbps":1000,"heightMm":166,"kind":"desktop","poe":false,"rearRj45":2,"widthMm":199},"formatVersion":1,"geometry":"Own flat interactive drawing; official photographs and PDF figures are private references only; approximate color.","hardwareRevision":null,"locators":{"dimensions":"Official datasheet PDFpage5: H166xW199xD223mm, desktop, two1GbE RJ45; PDFpage4 HardwareOverview.","ports":"Official HIG PDFpage4/printed3 AtAGlance LAN1-LAN2 left-to-right; USB1front1rear; DC12V circular bottom-left; two fans side-by-side. Table continuesPDFpage5."},"model":"DS423+","nonConnectableReferences":{"dcInput":1,"driveBays":4,"externalPowerAdapter":1,"fans":2,"usbFront":1,"usbRear":1},"ownSyntheticSupport":{"dimensionsMm":{"depth":300,"height":222,"width":482.6},"key":"shelf-5u","rackUnits":5,"revision":"mount-support-20261030-v1","scope":"Own generic dimensional reservation only. Not a Synology accessory. No mechanical load, fit, manufacturer ventilation clearance or airflow certification. Historical shelf-2u and its60mm slot stay unchanged.","slot":{"depthMm":300,"heightMm":190,"key":"main","widthMm":440}},"pdfSha256":"bf2db977fd378468d83a0b1a05bfbea8288b23d3eb0d53567a3f3dee538fd5b8","releaseDate":null,"retrieved":"2026-10-30","scope":"Exact DS423+ base model, not DS423 or DS923+. Only Ethernet ports are inventory connectors. DC input and its external adapter require a typed adapter contract before connectivity; no DC-to-AC-PDU link. USB, SATA/M.2, installed drives, storage contents and telemetry are not modeled. Four bays do not assert installed drives.","url":"https://global.download.synology.com/download/Document/Hardware/HIG/DiskStation/23-year/DS423%2B/enu/DS423p_HIG_enu.pdf"}')
pretty=g.pretty
literal=g.literal

def sql_source(models,pins):
    lines=['-- Auto-generated by tools/build_hardware_catalog22.py; SQL001-021 are frozen.',
      '-- DS423+ Ethernet only. External DC adapter, USB, disks and telemetry are out of scope.',
      '-- shelf-5u is an own synthetic reservation, not a Synology accessory or airflow certification.',
      '-- Existing sealing/publication triggers and runtime grants remain unchanged.']
    def insert(table,columns,values):lines.append('INSERT INTO '+table+' ('+columns+') VALUES ('+', '.join(map(literal,values))+');')
    for model,pin in zip(models,pins):
        pair=[model['key'],model['revision']];d=model['dimensionsMm']
        insert('hardware_definition','profile_key, revision, mount_kind, rack_units, width_mm, height_mm, depth_mm, color, definition_sha256, manufacturer, family, model, sku, provenance_kind, source_reference, sealed',pair+[model['kind'],model['rackUnits'],d['width'],d['height'],d['depth'],model['color'],pin['sha256']]+[model['identity'][key] for key in ('manufacturer','family','model','sku')]+[model['provenance']['kind'],model['provenance']['source'],False])
        for slot in model['slots']:
            sd=slot['dimensionsMm'];insert('hardware_mount_slot','profile_key, revision, slot_key, width_mm, height_mm, depth_mm',pair+[slot['key'],sd['width'],sd['height'],sd['depth']])
        for order,group in enumerate(model['groups']):
            insert('hardware_group_template','profile_key, revision, group_key, sort_order, type, port_count, face, name, prefix, power_role',pair+[group['key'],order,group['type'],group['count'],group['face'],group['name'],group['prefix'],group['powerRole']])
        lines.append('UPDATE hardware_definition SET sealed=true WHERE profile_key='+literal(pair[0])+' AND revision='+literal(pair[1])+';')
    return ('\n'.join(lines)+'\n').encode('utf-8')

def targets_source(inputs):
    return (g.targets_source(inputs).decode('ascii')
        .replace('build_hardware_catalog21.py','build_hardware_catalog22.py')
        .replace('Synology','DiskStation').replace('synology_catalog','diskstation_catalog')).encode('ascii')

def compile_catalog(root):
    raw={name:c.path(root,name).read_bytes() for name in (SOURCE,FACTS,LOCK,BASE)}
    source=c.load(raw[SOURCE]);facts=c.load(raw[FACTS]);lock=c.load(raw[LOCK])
    c.fields(lock,'formatVersion targetSchema sourceSha256 factsSha256 baseMigrationSha256 definitions state','diskstation_lock_invalid')
    c.require(type(lock['formatVersion']) is int and lock['formatVersion']==1 and type(lock['targetSchema']) is int and lock['targetSchema']==22 and lock['state']==STATE,'diskstation_target_unsupported')
    for name,field in ((SOURCE,'sourceSha256'),(FACTS,'factsSha256'),(BASE,'baseMigrationSha256')):c.require(c.sha(raw[name])==lock[field],'diskstation_input_changed')
    # Reviewed scope is closed even when an input is repinned by a caller.
    c.require(c.canonical(source)==c.canonical(EXPECTED_SOURCE),'diskstation_model_not_reviewed')
    c.require(c.canonical(facts)==c.canonical(EXPECTED_FACTS),'diskstation_facts_mismatch')
    models=source['definitions'];pins=[dict(key=m['key'],revision=m['revision'],sha256=c.sha(c.canonical(m))) for m in models]
    c.require(lock['definitions']==pins,'diskstation_definition_not_reviewed')
    server=c.server_source(source,commercial=True).decode('ascii').replace('tools/build_hardware_catalog.py;','tools/build_hardware_catalog22.py;').replace('internal static class CommercialHardwareProfiles','internal static class DiskStationHardwareProfiles')
    # Preserve the one-revision projection contract by emitting two catalogues.
    views=[]
    for model in models:
        view=c.projection(dict(definitions=[model]));view['synthetic']=model['provenance']['kind']=='own-synthetic'
        row=view['profiles'][0]
        if not view['synthetic']:
            row.update(identity=model['identity'],source=model['provenance']['source'])
        for group,original in zip(row['groups'],model['groups']):group['powerRole']=original['powerRole']
        views.append(view)
    outputs={SERVER:server.encode('ascii'),FRONTEND:pretty(views),SQL:sql_source(models,pins)}
    inputs={name:c.sha(value) for name,value in raw.items()}
    outputs[MANIFEST]=pretty(dict(formatVersion=1,targetSchema=22,catalogKey=source['catalogKey'],state=STATE,inputs=inputs,files={name:c.sha(value) for name,value in outputs.items()},definitions=pins))
    outputs[TARGETS]=targets_source({**inputs,**{name:c.sha(value) for name,value in outputs.items()}})
    return outputs

def run(root,write=False):
    outputs=compile_catalog(root);targets={name:c.path(root,name) for name in outputs}
    for target in targets.values():
        c.require(not target.exists() or target.is_file(),'diskstation_output_invalid')
        c.require(all(not p.exists() or p.is_dir() for p in target.parents),'diskstation_output_invalid')
    if write:
        staged={}
        try:
            for name,target in targets.items():
                target.parent.mkdir(parents=True,exist_ok=True);fd,temporary=tempfile.mkstemp(prefix='.catalog22-',dir=target.parent);staged[name]=temporary
                with os.fdopen(fd,'wb') as stream:stream.write(outputs[name]);stream.flush();os.fsync(stream.fileno())
            for name,target in targets.items():os.replace(staged[name],target)
        finally:
            for temporary in staged.values():
                if os.path.lexists(temporary):os.unlink(temporary)
    else:
        for name,target in targets.items():c.require(target.is_file() and target.read_bytes()==outputs[name],'diskstation_catalog_stale')
    return dict(status='written' if write else 'verified',targetSchema=22,definitions=2,files={name:c.sha(value) for name,value in outputs.items()},databaseChanged=False)

def main():
    parser=argparse.ArgumentParser(description=__doc__);mode=parser.add_mutually_exclusive_group(required=True);mode.add_argument('--check',action='store_true');mode.add_argument('--write',action='store_true');args=parser.parse_args()
    try:print(json.dumps(run(ROOT,write=args.write)));return 0
    except (c.CatalogError,OSError) as error:print(json.dumps(dict(status='failed',code=str(error) if isinstance(error,c.CatalogError) else 'diskstation_io_failed')));return 1
if __name__=='__main__':sys.exit(main())
